select *from Sales_customer

SELECT DISTINCT Region
FROM Sales_customer;

SELECT COUNT(*) FROM Sales_customer;

SELECT
    COUNT(*) AS Total_Rows,
    COUNT(DISTINCT Customer_Name) AS Unique_Customers,
    COUNT(DISTINCT Product) AS Unique_Products,
    COUNT(DISTINCT Region) AS Unique_Regions,
    COUNT(DISTINCT Gender) AS Unique_Genders
FROM Sales_customer;

SELECT
    Region,
    COUNT(*) AS Total
FROM Sales_customer
GROUP BY Region
ORDER BY Region;

SELECT
    Gender,
    COUNT(*) AS Total
FROM Sales_customer
GROUP BY Gender;

select * from  SALES where SALES > 500;


SELECT sales
FROM Sales_customer

SELECT SUM(CAST(sales AS DECIMAL(18,2))) AS total_sales
FROM Sales_customer;

    SELECT
    Order_ID,
    customer_name,
    product,
    region,
    quantity,
    unit_price,
    discount,
    sales,
    Order_Date,
    payment_method
FROM Sales_customer;

SELECT SUM(sales) AS total_sales
FROM Sales_customer;

SELECT
    region,
    SUM(sales) AS total_sales
FROM Sales_customer
GROUP BY region
ORDER BY total_sales DESC;

SELECT
    product,
    SUM(sales) AS total_sales
FROM Sales_customer
GROUP BY product
ORDER BY total_sales DESC;

SELECT
    product,
    SUM(quantity) AS total_quantity
FROM Sales_customer
GROUP BY product
ORDER BY total_quantity DESC;

SELECT
    customer_name,
    SUM(sales) AS total_sales
FROM Sales_customer
GROUP BY customer_name
ORDER BY total_sales DESC;

SELECT
    payment_method,
    COUNT(*) AS total_orders,
    SUM(sales) AS total_sales
FROM Sales_customer
GROUP BY payment_method
ORDER BY total_sales DESC;
  

